    print(f"   ({SEAT[c[0]]:<11} {KIND[c[1]]:<9} {ZC[c[2]]:<18}) : {', '.join(occ[c])}")

mod=[Counter(c[i] for c in cells).most_common(1)[0][0] for i in range(3)]
