        cs={tuple(p[i].index(x[i]) for i in range(3)) for x in cells}
        E=len(opR(cs,3))-len(cs)
        if best is None or E<best: best,arg=E,p
    return best,arg
axes=[4,2,2]
for corner,label in (((0,0,0),"the (<=,<=) origin"),((3,1,1),"the far corner")):
